head.script:
// 가이드 : iframe 내부 페이지에서 부모 팝업 창 닫기 — 팝업 XML (합성 화면, 호출 화면은 SMPIFR10000)

/*
 * 화면 동작
 * 1. 팝업 로딩시 $c.win.getPopupId() 로 자기 popupId 를 얻어 iframe src URL 에 ?popupId= 로 붙인다
 *    (호출 화면이 넘긴 파라미터도 함께 쿼리로 전달)
 * 2. window 'message' 이벤트 리스너를 등록해 iframe 페이지의 postMessage 를 기다린다
 * 3. iframe 페이지가 { execution: "closePopup", popupId, result } 를 보내면 popupId 가 자기 것일 때만
 *    $c.win.closePopup(result) 로 팝업을 닫고 result 를 부모(openPopup 의 await 결과)에 돌려준다
 * 4. 팝업이 닫힐 때(onpageunload) 리스너를 해제한다 — SPA 라 window 가 유지되므로 해제하지 않으면 팝업을 열 때마다 쌓인다
 *
 * 담긴 패턴
 * - 팝업 자기 식별 ($c.win.getPopupId) → iframe 에 전달 → 수신 메시지의 popupId 대조
 * - message 리스너의 생명주기 (onpageload 등록 · onpageunload 해제, 핸들러는 scwin 에 보관해 같은 참조로 해제)
 * - 수신 필터 3단계: event.origin(같은 출처) → event.data 형태(객체) → execution·popupId
 *   (WebSquare 엔진도 iframe 클릭·마우스다운·키업 전파용 { _wq_type: … } 객체를 같은 채널로 보내므로 반드시 골라낸다)
 * - 자기 팝업 닫기 ($c.win.closePopup(callbackParam) — 호출한 화면의 팝업을 닫으므로 popupId 를 넘기지 않는다)
 *
 * 변환 샘플과 달라진 곳
 * - 합성 가이드라 원본 없음. iframe 내부 페이지는 정적 HTML (/resources/sample/iframe-popup-close-sample.html)
 *
 * 복사해서 쓰는 순서
 * 1. 파일명과 meta_screenId 를 실제 화면ID 로 변경
 * 2. IFRAME_URL 을 실제 iframe 페이지로 교체 (다른 출처면 ALLOWED_ORIGIN 도 그 출처로)
 * 3. onIframeMessage 의 execution 값·result 형태를 iframe 페이지와 맞춤 (sendPopupMessage 의 messageData)
 * 4. 호출 화면은 SMPIFR10000 처럼 await $c.win.openPopup(...) 으로 결과를 받는다
 */


///////// 1. 변수 및 선언 영역 /////////

scwin.screenId = "SMPIFR10001";

// iframe 에 띄울 페이지 — 같은 출처(/resources/**)의 정적 HTML
scwin.IFRAME_URL = "/ui/sample/template/iframe-popup-close-sample.html";

// 수신을 허용할 출처 — iframe 페이지가 같은 출처이므로 location.origin. 다른 도메인이면 그 도메인으로 고정한다
scwin.ALLOWED_ORIGIN = location.origin;

// 자기 popupId — 수신 메시지의 popupId 와 대조해 다른 팝업의 iframe 메시지를 무시한다
scwin.popupId = "";


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 16
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "SMPIFR10001.onpageload" });
    }
};

/**
 * @method
 * @name scwin.onpageunload
 * @author Inswave
 * @date 2026. 09. 16
 * @description 페이지언로드. message 리스너를 해제한다 — 등록과 같은 함수 참조(scwin.onIframeMessage)여야 해제된다.
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageunload = function () {
    try {
        window.removeEventListener("message", scwin.onIframeMessage);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPIFR10001.onpageunload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 16
 * @description 초기화. popupId 를 얻어 iframe 을 띄우고 message 리스너를 등록한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - iframe 컴포넌트 id (ifr_page)
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    scwin.popupId = $c.win.getPopupId();

    // 호출 화면이 넘긴 파라미터(있으면) 를 iframe 에도 쿼리로 전달한다
    const param = $c.data.getParameter("pData") ?? {};

    // w2:tag(iframe) 의 실제 DOM 요소에 src 를 설정한다 — 컴포넌트 id 가 곧 DOM id 다
    document.querySelector("#ifr_page").src = scwin.buildIframeUrl(param);
    txb_popupId.setValue("이 팝업의 popupId : " + scwin.popupId);

    // iframe 페이지의 postMessage 수신 — 해제를 위해 반드시 scwin 에 보관한 같은 참조로 등록한다
    window.addEventListener("message", scwin.onIframeMessage);
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_close_onclick
 * @author Inswave
 * @date 2026. 09. 16
 * @description 팝업 자체의 닫기 버튼. 결과 없이 닫는다 (호출 화면의 await 결과는 undefined).
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_close_onclick = function () {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPIFR10001.btn_close_onclick" });
    }
};

/**
 * @event
 * @name scwin.onIframeMessage
 * @author Inswave
 * @date 2026. 09. 16
 * @description window 'message' 수신. iframe 페이지의 닫기 요청만 골라 자기 팝업을 닫고 result 를 부모에 돌려준다.
 *
 * 필터 순서: 출처 → 데이터 형태 → execution → popupId. 엔진의 { _wq_type } 전파 메시지는 execution 이 없어 여기서 걸러진다.
 * DOM 이벤트 핸들러라 진입점으로 보고 try/catch 를 둔다.
 * @param {MessageEvent} event postMessage 이벤트
 * @returns
 * @hidden N
*/
scwin.onIframeMessage = function (event) {
    try {
        if (event.origin !== scwin.ALLOWED_ORIGIN) return;

        const data = event.data;

        if (!data || typeof data !== "object") return;
        if (data.execution !== "closePopup") return;
        if (data.popupId !== scwin.popupId) return;   // 다른 팝업의 iframe 메시지

        // 자기 팝업을 닫는다. result 가 없으면(취소) 부모의 await 결과는 undefined 다
        $c.win.closePopup(data.result);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPIFR10001.onIframeMessage" });
    }
};


///////// 4. 서브미션 콜백 영역 /////////


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.buildIframeUrl
 * @author Inswave
 * @date 2026. 09. 16
 * @description iframe URL 을 만든다. popupId 는 필수이고, 호출 화면 파라미터는 문자열 값만 쿼리로 덧붙인다.
 * @param {Object} param 호출 화면이 넘긴 파라미터
 * @returns {String} 쿼리가 붙은 iframe URL
 * @hidden N
*/
scwin.buildIframeUrl = function (param) {
    const query = new URLSearchParams();

    query.set("popupId", scwin.popupId);

    Object.keys(param || {}).forEach(function (key) {
        if (typeof param[key] === "string" || typeof param[key] === "number") {
            query.set(key, String(param[key]));
        }
    });

    return scwin.IFRAME_URL + "?" + query.toString();
};
